use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let t: usize = iter.next().unwrap().parse().unwrap();
    let mut output = String::new();

    for _ in 0..t {
        let n: usize = iter.next().unwrap().parse().unwrap();
        let mut prefix = vec![0_i64; n + 1];

        for i in 0..n {
            let value: i64 = iter.next().unwrap().parse().unwrap();
            prefix[i + 1] = prefix[i] + value;
        }

        let mut answer = 0_i64;

        for k in 1..=n {
            if n % k != 0 {
                continue;
            }

            let mut minimum = i64::MAX;
            let mut maximum = i64::MIN;

            for start in (0..n).step_by(k) {
                let sum = prefix[start + k] - prefix[start];
                minimum = minimum.min(sum);
                maximum = maximum.max(sum);
            }

            answer = answer.max(maximum - minimum);
        }

        output.push_str(&format!("{answer}\n"));
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
