use std::io::{self, Read, Write};

fn parse_numbers(line: &str) -> Vec<usize> {
    line.split(|c: char| !c.is_ascii_digit())
        .filter(|s| !s.is_empty())
        .map(|s| s.parse::<usize>().unwrap())
        .collect()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let arrays: Vec<Vec<usize>> = input
        .lines()
        .map(parse_numbers)
        .filter(|values| !values.is_empty())
        .collect();

    if arrays.len() < 2 {
        return;
    }

    let cost = &arrays[0];
    let time = &arrays[1];
    let n = cost.len().min(time.len());

    let inf = i64::MAX / 4;
    let mut dp = vec![inf; n + 1];
    dp[0] = 0;

    for i in 0..n {
        let walls_covered = time[i] + 1;
        for painted in (0..=n).rev() {
            if dp[painted] == inf {
                continue;
            }
            let next = n.min(painted + walls_covered);
            dp[next] = dp[next].min(dp[painted] + cost[i] as i64);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", dp[n]).unwrap();
}
