use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let tokens: Vec<&str> = input.split_whitespace().collect();

    if tokens.is_empty() {
        return;
    }

    let start = match tokens[0].parse::<usize>() {
        Ok(n) if n == tokens.len() - 1 => 1,
        _ => 0,
    };
    let words = &tokens[start..];

    if words.is_empty() {
        return;
    }

    const INF: usize = usize::MAX / 4;
    let mut dp = [[INF; 26]; 26];

    let first = words[0].as_bytes();
    let left = (first[0] - b'a') as usize;
    let right = (first[first.len() - 1] - b'a') as usize;
    dp[left][right] = first.len();

    for word in &words[1..] {
        let bytes = word.as_bytes();
        let word_left = (bytes[0] - b'a') as usize;
        let word_right = (bytes[bytes.len() - 1] - b'a') as usize;
        let len = bytes.len();

        let mut next = [[INF; 26]; 26];

        for current_left in 0..26 {
            for current_right in 0..26 {
                let current = dp[current_left][current_right];
                if current == INF {
                    continue;
                }

                // join(current_string, word)
                let append_cost = current + len - usize::from(current_right == word_left);
                next[current_left][word_right] =
                    next[current_left][word_right].min(append_cost);

                // join(word, current_string)
                let prepend_cost = current + len - usize::from(word_right == current_left);
                next[word_left][current_right] =
                    next[word_left][current_right].min(prepend_cost);
            }
        }

        dp = next;
    }

    let answer = dp.iter().flatten().copied().min().unwrap();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
