fn max_digit(mut n: i32) -> usize {
    let mut maximum = 0;
    while n > 0 {
        maximum = maximum.max(n % 10);
        n /= 10;
    }
    maximum as usize
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let nums = input
        .split_whitespace()
        .filter_map(|s| s.parse::<i32>().ok());

    let mut largest = [-1_i32; 10];
    let mut answer = -1_i32;

    for num in nums {
        let digit = max_digit(num);
        if largest[digit] != -1 {
            answer = answer.max(largest[digit] + num);
        }
        largest[digit] = largest[digit].max(num);
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
