use std::io::{self, Read, Write};

fn parse_numbers(line: &str) -> Vec<i64> {
    let bytes = line.as_bytes();
    let mut result = Vec::new();
    let mut i = 0;

    while i < bytes.len() {
        while i < bytes.len() && !bytes[i].is_ascii_digit() && bytes[i] != b'-' {
            i += 1;
        }
        if i >= bytes.len() {
            break;
        }

        let mut sign = 1i64;
        if bytes[i] == b'-' {
            sign = -1;
            i += 1;
        }

        let mut value = 0i64;
        let mut found_digit = false;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            found_digit = true;
            value = value * 10 + (bytes[i] - b'0') as i64;
            i += 1;
        }

        if found_digit {
            result.push(sign * value);
        }
    }

    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let lines: Vec<&str> = input.lines().filter(|line| !line.trim().is_empty()).collect();
    if lines.len() < 3 {
        return;
    }

    let nums1 = parse_numbers(lines[0]);
    let nums2 = parse_numbers(lines[1]);
    let x = parse_numbers(lines[2])[0];

    let n = nums1.len();
    let sum1: i64 = nums1.iter().sum();
    let sum2: i64 = nums2.iter().sum();

    let mut pairs: Vec<(i64, i64)> = nums1.into_iter().zip(nums2).collect();
    pairs.sort_unstable_by_key(|&(_, b)| b);

    let neg_inf = i64::MIN / 4;
    let mut dp = vec![neg_inf; n + 1];
    dp[0] = 0;

    for (processed, &(a, b)) in pairs.iter().enumerate() {
        for selected in (1..=processed + 1).rev() {
            dp[selected] = dp[selected].max(
                dp[selected - 1] + a + b * selected as i64
            );
        }
    }

    let mut answer = -1i64;
    for time in 0..=n {
        let remaining_sum = sum1 + sum2 * time as i64 - dp[time];
        if remaining_sum <= x {
            answer = time as i64;
            break;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
