use std::io::{self, Read, Write};

fn count_beautiful(n: i64, k: usize) -> i64 {
    if n <= 0 {
        return 0;
    }

    let digits: Vec<usize> = n
        .to_string()
        .bytes()
        .map(|b| (b - b'0') as usize)
        .collect();
    let len = digits.len();
    let balance_size = 2 * len + 1;
    let mut memo = vec![vec![vec![vec![-1_i64; 2]; balance_size]; k]; len + 1];

    fn dfs(
        pos: usize,
        remainder: usize,
        balance: isize,
        started: bool,
        tight: bool,
        digits: &[usize],
        k: usize,
        offset: isize,
        memo: &mut Vec<Vec<Vec<Vec<i64>>>>,
    ) -> i64 {
        if pos == digits.len() {
            return if started && remainder == 0 && balance == 0 {
                1
            } else {
                0
            };
        }

        let balance_index = (balance + offset) as usize;
        let started_index = started as usize;

        if !tight {
            let cached = memo[pos][remainder][balance_index][started_index];
            if cached != -1 {
                return cached;
            }
        }

        let limit = if tight { digits[pos] } else { 9 };
        let mut result = 0_i64;

        for digit in 0..=limit {
            let next_tight = tight && digit == limit;

            if !started && digit == 0 {
                result += dfs(
                    pos + 1,
                    0,
                    balance,
                    false,
                    next_tight,
                    digits,
                    k,
                    offset,
                    memo,
                );
            } else {
                let next_remainder = (remainder * 10 + digit) % k;
                let next_balance = if digit % 2 == 0 {
                    balance + 1
                } else {
                    balance - 1
                };

                result += dfs(
                    pos + 1,
                    next_remainder,
                    next_balance,
                    true,
                    next_tight,
                    digits,
                    k,
                    offset,
                    memo,
                );
            }
        }

        if !tight {
            memo[pos][remainder][balance_index][started_index] = result;
        }

        result
    }

    dfs(
        0,
        0,
        0,
        false,
        true,
        &digits,
        k,
        len as isize,
        &mut memo,
    )
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace().map(|s| s.parse::<i64>().unwrap());

    let low = values.next().unwrap();
    let high = values.next().unwrap();
    let k = values.next().unwrap() as usize;

    let answer = count_beautiful(high, k) - count_beautiful(low - 1, k);

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
}
