    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let values: Vec<i64> = input
        .split(|c: char| !c.is_ascii_digit())
        .filter(|s| !s.is_empty())
        .map(|s| s.parse::<i64>().unwrap())
        .collect();

    if values.len() < 2 {
        return;
    }

    let target = *values.last().unwrap();
    let nums = &values[..values.len() - 1];

    let total: i64 = nums.iter().sum();
    if total < target {
        println!("-1");
        return;
    }

    let mut count = [0i64; 64];
    for &num in nums {
        let bit = num.trailing_zeros() as usize;
        count[bit] += 1;
    }

    let mut operations = 0i64;

    for bit in 0..31usize {
        if ((target >> bit) & 1) != 0 {
            if count[bit] > 0 {
                count[bit] -= 1;
            } else {
                let mut higher = bit + 1;
                while higher < count.len() && count[higher] == 0 {
                    higher += 1;
                }

                if higher == count.len() {
                    println!("-1");
                    return;
                }

                while higher > bit {
                    count[higher] -= 1;
                    count[higher - 1] += 2;
                    operations += 1;
                    higher -= 1;
                }

                count[bit] -= 1;
            }
        }

        count[bit + 1] += count[bit] / 2;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{operations}").unwrap();
}
