    let total: i64 = nums.iter().sum();
    let full_cycles = target / total;
    let remainder = target % total;

    let answer = if remainder == 0 {
        full_cycles * n as i64
    } else {
        let mut left = 0usize;
        let mut sum = 0i64;
        let mut shortest = usize::MAX;

        for right in 0..(2 * n) {
            sum += nums[right % n];

            while left <= right && (sum > remainder || right - left + 1 > n) {
                sum -= nums[left % n];
                left += 1;
            }

            if sum == remainder && left < n {
                shortest = shortest.min(right - left + 1);
            }
        }

        if shortest == usize::MAX {
            -1
        } else {
            full_cycles * n as i64 + shortest as i64
        }
    };

