use std::io::{self, Read, Write};

fn solve(nums1: &[i64], nums2: &[i64]) -> i32 {
    let n = nums1.len();
    let mut answer = i32::MAX;

    for swap_last in [false, true] {
        let (max1, max2) = if swap_last {
            (nums2[n - 1], nums1[n - 1])
        } else {
            (nums1[n - 1], nums2[n - 1])
        };

        let mut operations = if swap_last { 1 } else { 0 };
        let mut possible = true;

        for i in 0..n - 1 {
            let keep_valid = nums1[i] <= max1 && nums2[i] <= max2;
            let swap_valid = nums2[i] <= max1 && nums1[i] <= max2;

            if keep_valid {
                continue;
            } else if swap_valid {
                operations += 1;
            } else {
                possible = false;
                break;
            }
        }

        if possible {
            answer = answer.min(operations);
        }
    }

    if answer == i32::MAX { -1 } else { answer }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let rows: Vec<Vec<i64>> = input
        .lines()
        .map(|line| {
            line.split(|c: char| !c.is_ascii_digit() && c != '-')
                .filter(|s| !s.is_empty())
                .map(|s| s.parse::<i64>().unwrap())
                .collect::<Vec<_>>()
        })
        .filter(|row| !row.is_empty())
        .collect();

    let (nums1, nums2) = if rows.len() >= 3
        && rows[0].len() == 1
        && rows[1].len() == rows[0][0] as usize
        && rows[2].len() == rows[0][0] as usize
    {
        (&rows[1], &rows[2])
    } else {
        (&rows[0], &rows[1])
    };

    let result = solve(nums1, nums2);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{result}").unwrap();
