use std::io::{self, Read, Write};

fn update_count(
    counts: &mut [usize; 26],
    idx: usize,
    delta: isize,
    k: usize,
    nonzero: &mut usize,
    exact: &mut usize,
) {
    let old = counts[idx];

    if old > 0 {
        *nonzero -= 1;
    }
    if old == k {
        *exact -= 1;
    }

    let new = (old as isize + delta) as usize;
    counts[idx] = new;

    if new > 0 {
        *nonzero += 1;
    }
    if new == k {
        *exact += 1;
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let word = iter.next().unwrap().as_bytes();
    let k: usize = iter.next().unwrap().parse().unwrap();
    let n = word.len();

    let mut answer: i64 = 0;
    let mut segment_start = 0;

    while segment_start < n {
        let mut segment_end = segment_start + 1;

        while segment_end < n {
            let a = word[segment_end - 1] as i32;
            let b = word[segment_end] as i32;
            if (a - b).abs() > 2 {
                break;
            }
            segment_end += 1;
        }

        let segment_len = segment_end - segment_start;
        let max_distinct = 26usize.min(segment_len / k);

        for distinct in 1..=max_distinct {
            let window_len = distinct * k;
            let mut counts = [0usize; 26];
            let mut nonzero = 0usize;
            let mut exact = 0usize;

            for &ch in &word[segment_start..segment_start + window_len] {
                update_count(
                    &mut counts,
                    (ch - b'a') as usize,
                    1,
                    k,
                    &mut nonzero,
                    &mut exact,
                );
            }

            if nonzero == distinct && exact == distinct {
                answer += 1;
            }

            let mut right = segment_start + window_len;
            while right < segment_end {
                let removed = (word[right - window_len] - b'a') as usize;
                let added = (word[right] - b'a') as usize;

                update_count(
                    &mut counts,
                    removed,
                    -1,
                    k,
                    &mut nonzero,
                    &mut exact,
                );
                update_count(
                    &mut counts,
                    added,
                    1,
                    k,
                    &mut nonzero,
                    &mut exact,
                );

                if nonzero == distinct && exact == distinct {
                    answer += 1;
                }

                right += 1;
            }
        }

        segment_start = segment_end;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
