use std::collections::HashMap;
use std::io::{self, Read, Write};

fn solve(x: i64, y: i64, memo: &mut HashMap<i64, i64>) -> i64 {
    if x <= y {
        return y - x;
    }
    if let Some(&answer) = memo.get(&x) {
        return answer;
    }

    let mut answer = x - y;

    for divisor in [5_i64, 11_i64] {
        let remainder = x % divisor;

        // Decrement to the nearest lower multiple, then divide.
        answer = answer.min(
            remainder + 1 + solve(x / divisor, y, memo)
        );

        // Increment to the nearest higher multiple, then divide.
        if remainder != 0 {
            answer = answer.min(
                (divisor - remainder) + 1 + solve(x / divisor + 1, y, memo)
            );
        }
    }

    memo.insert(x, answer);
    answer
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace().filter_map(|s| s.parse::<i64>().ok());

    let x = values.next().unwrap();
    let y = values.next().unwrap();

    let answer = solve(x, y, &mut HashMap::new());

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
