        if n % len != 0 {
            continue;
        }

        let mut target = [0usize; 26];
        for &byte in &s[..len] {
            target[(byte - b'a') as usize] += 1;
        }

        let mut valid = true;
        for chunk in s[len..].chunks(len) {
            let mut counts = [0usize; 26];
            for &byte in chunk {
                counts[(byte - b'a') as usize] += 1;
            }
            if counts != target {
                valid = false;
                break;
            }
        }

        if valid {
            answer = len;
            break;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
