use std::collections::VecDeque;
use std::io::{self, Read, Write};

fn tree_diameter(adj: &[Vec<usize>]) -> usize {
    fn farthest(start: usize, adj: &[Vec<usize>]) -> (usize, usize) {
        let mut dist = vec![usize::MAX; adj.len()];
        let mut queue = VecDeque::new();
        dist[start] = 0;
        queue.push_back(start);

        let mut far_node = start;
        while let Some(node) = queue.pop_front() {
            if dist[node] > dist[far_node] {
                far_node = node;
            }
            for &next in &adj[node] {
                if dist[next] == usize::MAX {
                    dist[next] = dist[node] + 1;
                    queue.push_back(next);
                }
            }
        }

        (far_node, dist[far_node])
    }

    if adj.len() <= 1 {
        return 0;
    }

    let (endpoint, _) = farthest(0, adj);
    let (_, diameter) = farthest(endpoint, adj);
    diameter
}

fn read_tree<'a, I>(iter: &mut I) -> Vec<Vec<usize>>
where
    I: Iterator<Item = &'a str>,
{
    let edge_count: usize = iter.next().unwrap().parse().unwrap();
    let node_count = edge_count + 1;
    let mut adj = vec![Vec::new(); node_count];

    for _ in 0..edge_count {
        let a: usize = iter.next().unwrap().parse().unwrap();
        let b: usize = iter.next().unwrap().parse().unwrap();
        adj[a].push(b);
        adj[b].push(a);
    }

    adj
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let tree1 = read_tree(&mut iter);
    let tree2 = read_tree(&mut iter);

    let d1 = tree_diameter(&tree1);
    let d2 = tree_diameter(&tree2);

    let combined = (d1 + 1) / 2 + (d2 + 1) / 2 + 1;
    let answer = d1.max(d2).max(combined);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
