use std::io::{self, Read, Write};

fn triangle_count(limit: i64) -> i64 {
    if limit < 0 {
        0
    } else {
        (limit + 1) * (limit + 2) / 2
    }
}

fn count_sum_at_most(limit: i64, max_a: i64, max_b: i64) -> i64 {
    triangle_count(limit)
        - triangle_count(limit - max_a - 1)
        - triangle_count(limit - max_b - 1)
        + triangle_count(limit - max_a - max_b - 2)
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let s: Vec<u8> = input
        .trim()
        .trim_matches('"')
        .bytes()
        .filter(|&c| c == b'0' || c == b'1')
        .collect();

    let n = s.len();
    let mut zeros = Vec::new();
    let mut answer: i64 = 0;

    // Substrings with no zeros: all nonempty substrings of each run of ones.
    let mut ones_run = 0i64;
    for (i, &c) in s.iter().enumerate() {
        if c == b'1' {
            ones_run += 1;
        } else {
            answer += ones_run * (ones_run + 1) / 2;
            ones_run = 0;
            zeros.push(i as i64);
        }
    }
    answer += ones_run * (ones_run + 1) / 2;

    let zero_count = zeros.len();
    let mut k = 1usize;

    while k * (k + 1) <= n && k <= zero_count {
        let required_length = (k * (k + 1)) as i64;

        for i in 0..=zero_count - k {
            let first_zero = zeros[i];
            let last_zero = zeros[i + k - 1];

            let previous_zero = if i == 0 { -1 } else { zeros[i - 1] };
            let next_zero = if i + k == zero_count {
                n as i64
            } else {
                zeros[i + k]
            };

            let max_left_extension = first_zero - previous_zero - 1;
            let max_right_extension = next_zero - last_zero - 1;
            let core_length = last_zero - first_zero + 1;
            let needed_extension = required_length - core_length;

            let total_choices =
                (max_left_extension + 1) * (max_right_extension + 1);

            if needed_extension <= 0 {
                answer += total_choices;
            } else {
                let invalid = count_sum_at_most(
                    needed_extension - 1,
                    max_left_extension,
                    max_right_extension,
                );
                answer += total_choices - invalid;
            }
        }

        k += 1;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
