                let required = worker_time as i128 * mid as i128 * (mid as i128 + 1) / 2;

                if required <= time as i128 {
                    left = mid;
                } else {
                    right = mid - 1;
                }
            }

            total_reduced += left;
            if total_reduced >= height {
                break;
            }
        }

        if total_reduced >= height {
            high = time;
        } else {
            low = time + 1;
        }
