use std::io::{self, Read, Write};

struct FenwickMax {
    tree: Vec<usize>,
}

impl FenwickMax {
    fn new(n: usize) -> Self {
        Self {
            tree: vec![0; n + 1],
        }
    }

    fn update(&mut self, mut index: usize, value: usize) {
        while index < self.tree.len() {
            self.tree[index] = self.tree[index].max(value);
            index += index & index.wrapping_neg();
        }
    }

    fn query(&self, mut index: usize) -> usize {
        let mut result = 0;
        while index > 0 {
            result = result.max(self.tree[index]);
            index &= index - 1;
        }
        result
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut coordinates = Vec::with_capacity(n);
    let mut ys = Vec::with_capacity(n);

    for _ in 0..n {
        let x: u64 = iter.next().unwrap().parse().unwrap();
        let y: u64 = iter.next().unwrap().parse().unwrap();
        coordinates.push((x, y));
        ys.push(y);
    }

    let k: usize = iter.next().unwrap().parse().unwrap();

    ys.sort_unstable();
    ys.dedup();
    let y_count = ys.len();

    let ranks: Vec<usize> = coordinates
        .iter()
        .map(|&(_, y)| ys.binary_search(&y).unwrap() + 1)
        .collect();

    let mut order: Vec<usize> = (0..n).collect();
    order.sort_unstable_by_key(|&i| coordinates[i].0);

    // Longest increasing path ending at coordinates[k].
    let mut fenwick = FenwickMax::new(y_count);
    let mut ending_at_target = 1;
    let mut start = 0;

    while start < n {
        let x = coordinates[order[start]].0;
        let mut end = start;
        let mut pending = Vec::new();

        while end < n && coordinates[order[end]].0 == x {
            let index = order[end];
            let rank = ranks[index];
            let length = fenwick.query(rank - 1) + 1;

            if index == k {
                ending_at_target = length;
            }

            pending.push((rank, length));
            end += 1;
        }

        for (rank, length) in pending {
            fenwick.update(rank, length);
        }

        start = end;
    }

    // Longest increasing path starting at coordinates[k].
    order.sort_unstable_by(|&a, &b| coordinates[b].0.cmp(&coordinates[a].0));

    let mut fenwick = FenwickMax::new(y_count);
    let mut starting_at_target = 1;
    start = 0;

    while start < n {
        let x = coordinates[order[start]].0;
        let mut end = start;
        let mut pending = Vec::new();

        while end < n && coordinates[order[end]].0 == x {
            let index = order[end];
            let rank = ranks[index];
            let reversed_rank = y_count - rank + 1;
            let length = fenwick.query(reversed_rank - 1) + 1;

            if index == k {
                starting_at_target = length;
            }

            pending.push((reversed_rank, length));
            end += 1;
        }

        for (rank, length) in pending {
            fenwick.update(rank, length);
        }

        start = end;
    }

    let answer = ending_at_target + starting_at_target - 1;

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
}
