    let mut min_cost = [[0u64; 26]; 26];

    for start in 0..26 {
        for target in 0..26 {
            let mut forward = 0u64;
            let mut current = start;
            while current != target {
                forward += next_cost[current];
                current = (current + 1) % 26;
            }

            let mut backward = 0u64;
            current = start;
            while current != target {
                backward += previous_cost[current];
                current = (current + 25) % 26;
            }

            min_cost[start][target] = forward.min(backward);
        }
    }

    let mut answer = 0u64;
    for (&from, &to) in s.iter().zip(t.iter()) {
        answer += min_cost[(from - b'a') as usize][(to - b'a') as usize];
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
