use std::collections::HashMap;
use std::io::{self, Read, Write};

fn get_id(
    name: &str,
    ids: &mut HashMap<String, usize>,
) -> usize {
    if let Some(&id) = ids.get(name) {
        return id;
    }
    let id = ids.len();
    ids.insert(name.to_string(), id);
    id
}

fn conversion_values(
    graph: &[Vec<(usize, f64)>],
    start: usize,
) -> Vec<Option<f64>> {
    let mut values = vec![None; graph.len()];
    let mut stack = vec![start];
    values[start] = Some(1.0);

    while let Some(node) = stack.pop() {
        let current = values[node].unwrap();
        for &(next, rate) in &graph[node] {
            if values[next].is_none() {
                values[next] = Some(current * rate);
                stack.push(next);
            }
        }
    }

    values
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();

    let initial_currency = tokens.next().unwrap();
    let mut ids = HashMap::new();
    let initial_id = get_id(initial_currency, &mut ids);

    let n: usize = tokens.next().unwrap().parse().unwrap();
    let mut day1_pairs = Vec::with_capacity(n);
    for _ in 0..n {
        let from = tokens.next().unwrap();
        let to = tokens.next().unwrap();
        let from_id = get_id(from, &mut ids);
        let to_id = get_id(to, &mut ids);
        day1_pairs.push((from_id, to_id));
    }

    let mut day1_edges = Vec::with_capacity(n);
    for pair in day1_pairs {
        let rate: f64 = tokens.next().unwrap().parse().unwrap();
        day1_edges.push((pair.0, pair.1, rate));
    }

    let m: usize = tokens.next().unwrap().parse().unwrap();
    let mut day2_pairs = Vec::with_capacity(m);
    for _ in 0..m {
        let from = tokens.next().unwrap();
        let to = tokens.next().unwrap();
        let from_id = get_id(from, &mut ids);
        let to_id = get_id(to, &mut ids);
        day2_pairs.push((from_id, to_id));
    }

    let mut day2_edges = Vec::with_capacity(m);
    for pair in day2_pairs {
        let rate: f64 = tokens.next().unwrap().parse().unwrap();
        day2_edges.push((pair.0, pair.1, rate));
    }

    let currency_count = ids.len();
    let mut graph1 = vec![Vec::new(); currency_count];
    let mut graph2 = vec![Vec::new(); currency_count];

    for (from, to, rate) in day1_edges {
        graph1[from].push((to, rate));
        graph1[to].push((from, 1.0 / rate));
    }

    for (from, to, rate) in day2_edges {
        graph2[from].push((to, rate));
        graph2[to].push((from, 1.0 / rate));
    }

    let day1_values = conversion_values(&graph1, initial_id);
    let day2_values = conversion_values(&graph2, initial_id);

    let mut answer = 1.0_f64;
    for currency in 0..currency_count {
        if let (Some(day1_amount), Some(initial_to_currency_day2)) =
            (day1_values[currency], day2_values[currency])
        {
            answer = answer.max(day1_amount / initial_to_currency_day2);
        }
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{:?}", answer).unwrap();
}
