use std::cmp::Reverse;
use std::collections::BinaryHeap;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();

    let n: usize = values.next().unwrap().parse().unwrap();
    let cells: Vec<u64> = values.map(|s| s.parse().unwrap()).collect();
    let m = cells.len() / n;

    let mut dist = vec![u64::MAX; n * m];
    let mut heap = BinaryHeap::new();

    dist[0] = 0;
    heap.push(Reverse((0_u64, 0_usize)));

    while let Some(Reverse((time, pos))) = heap.pop() {
        if time != dist[pos] {
            continue;
        }
        if pos == n * m - 1 {
            break;
        }

        let row = pos / m;
        let col = pos % m;

        let mut relax = |next: usize| {
            let next_time = time.max(cells[next]) + 1;
            if next_time < dist[next] {
                dist[next] = next_time;
                heap.push(Reverse((next_time, next)));
            }
        };

        if row > 0 {
            relax(pos - m);
        }
        if row + 1 < n {
            relax(pos + m);
        }
        if col > 0 {
            relax(pos - 1);
        }
        if col + 1 < m {
            relax(pos + 1);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", dist[n * m - 1]).unwrap();
}
