use std::collections::BinaryHeap;
use std::io::{self, Read, Write};

fn parse_numbers(line: &str) -> Vec<i64> {
    line.split(|c: char| !(c.is_ascii_digit() || c == '-'))
        .filter(|s| !s.is_empty() && *s != "-")
        .filter_map(|s| s.parse::<i64>().ok())
        .collect()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines().filter(|line| !line.trim().is_empty());

    let nums: Vec<i32> = match lines.next() {
        Some(line) => parse_numbers(line).into_iter().map(|x| x as i32).collect(),
        None => return,
    };

    let query_count = match lines.next() {
        Some(line) => parse_numbers(line).first().copied().unwrap_or(0) as usize,
        None => return,
    };

    let remaining: Vec<i64> = lines.flat_map(parse_numbers).collect();
    let n = nums.len();
    let mut starts = vec![Vec::<usize>::new(); n];

    for i in 0..query_count {
        let l = remaining[2 * i] as usize;
        let r = remaining[2 * i + 1] as usize;
        starts[l].push(r);
    }

    let mut available = BinaryHeap::<usize>::new();
    let mut difference = vec![0i32; n + 1];
    let mut coverage = 0i32;
    let mut used = 0usize;
    let mut possible = true;

    for i in 0..n {
        coverage += difference[i];

        for &r in &starts[i] {
            available.push(r);
        }

        while coverage < nums[i] {
            match available.pop() {
                Some(r) if r >= i => {
                    used += 1;
                    coverage += 1;
                    difference[r + 1] -= 1;
                }
                _ => {
                    possible = false;
                    break;
                }
            }
        }

        if !possible {
            break;
        }
    }

    let answer = if possible {
        query_count as i64 - used as i64
    } else {
        -1
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
