fn main() {
    const MOD: u64 = 1_000_000_007;

    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let lines: Vec<&str> = input
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .collect();

    if lines.is_empty() {
        return;
    }

    let m: usize = lines[0].parse().unwrap();
    let mut grid = Vec::with_capacity(m);

    for i in 0..m {
        let row: Vec<usize> = lines[i + 1]
            .split_whitespace()
            .map(|s| s.parse().unwrap())
            .collect();
        grid.push(row);
    }

    let k: usize = lines[m + 1].parse().unwrap();
    let n = grid[0].len();

    let mut dp = vec![[0u64; 16]; n];

    for i in 0..m {
        for j in 0..n {
            let value = grid[i][j];
            let mut current = [0u64; 16];

            if i == 0 && j == 0 {
                current[value] = 1;
            } else {
                for xor_value in 0..16 {
                    let mut count = dp[j][xor_value];
                    if j > 0 {
                        count += dp[j - 1][xor_value];
                    }
                    current[xor_value ^ value] = count % MOD;
                }
            }

            dp[j] = current;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{}", dp[n - 1][k]).unwrap();
