use std::io::{self, Read, Write};

fn prefix_coins(x: i64, segments: &[(i64, i64, i64)], prefix: &[i64]) -> i64 {
    let mut low = 0usize;
    let mut high = segments.len();

    while low < high {
        let mid = low + (high - low) / 2;
        if segments[mid].0 <= x {
            low = mid + 1;
        } else {
            high = mid;
        }
    }

    if low == 0 {
        return 0;
    }

    let i = low - 1;
    let (l, r, c) = segments[i];
    let covered = if x >= r {
        r - l + 1
    } else {
        x - l + 1
    };

    prefix[i] + covered * c
}

fn window_sum(
    start: i64,
    k: i64,
    segments: &[(i64, i64, i64)],
    prefix: &[i64],
) -> i64 {
    prefix_coins(start + k - 1, segments, prefix)
        - prefix_coins(start - 1, segments, prefix)
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut segments = Vec::with_capacity(n);

    for _ in 0..n {
        let l: i64 = iter.next().unwrap().parse().unwrap();
        let r: i64 = iter.next().unwrap().parse().unwrap();
        let c: i64 = iter.next().unwrap().parse().unwrap();
        segments.push((l, r, c));
    }

    let k: i64 = iter.next().unwrap().parse().unwrap();

    segments.sort_unstable_by_key(|&(l, _, _)| l);

    let mut prefix = vec![0i64; n + 1];
    for i in 0..n {
        let (l, r, c) = segments[i];
        prefix[i + 1] = prefix[i] + (r - l + 1) * c;
    }

    let mut answer = 0i64;

    for &(l, r, _) in &segments {
        answer = answer.max(window_sum(l, k, &segments, &prefix));
        answer = answer.max(window_sum(r - k + 1, k, &segments, &prefix));
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
