use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let nums: Vec<usize> = input
        .split(|c: char| !c.is_ascii_digit())
        .filter(|s| !s.is_empty())
        .map(|s| s.parse().unwrap())
        .collect();

    if nums.is_empty() {
        return;
    }

    const MAX_VALUE: usize = 300;
    const MAX_DIFF: usize = 299;

    // dp[value][diff] is the maximum subsequence length ending at `value`
    // whose last adjacent difference is exactly `diff`.
    let mut dp = vec![vec![0u16; MAX_DIFF + 1]; MAX_VALUE + 1];

    // suffix[value][diff] is max(dp[value][d]) over d >= diff.
    let mut suffix = vec![vec![0u16; MAX_DIFF + 1]; MAX_VALUE + 1];
    let mut seen = vec![false; MAX_VALUE + 1];

    let mut answer = 1u16;

    for x in nums {
        let mut candidates = [0u16; MAX_DIFF + 1];

        for y in 1..=MAX_VALUE {
            if !seen[y] {
                continue;
            }

            let diff = x.abs_diff(y);
            let previous = suffix[y][diff];
            let length = if previous == 0 { 2 } else { previous + 1 };
            candidates[diff] = candidates[diff].max(length);
        }

        for diff in 0..=MAX_DIFF {
            if candidates[diff] > dp[x][diff] {
                dp[x][diff] = candidates[diff];
                answer = answer.max(candidates[diff]);
            }
        }

        let mut best = 0u16;
        for diff in (0..=MAX_DIFF).rev() {
            best = best.max(dp[x][diff]);
            suffix[x][diff] = best;
        }

        seen[x] = true;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
