        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let mut coupons: Vec<(i64, i64)> = limits.into_iter().zip(discounts).collect();

    prices.sort_unstable();
    coupons.sort_unstable_by_key(|&(limit, _)| limit);

    let mut total: i64 = prices.iter().sum();
    let mut available = BinaryHeap::new();
    let mut coupon_index = 0;

    for price in prices {
        while coupon_index < m && coupons[coupon_index].0 <= price {
            available.push(coupons[coupon_index].1);
            coupon_index += 1;
        }

        if let Some(discount) = available.pop() {
            total -= discount;
        }
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{total}").unwrap();
}
