use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut points = Vec::with_capacity(n);

    for _ in 0..n {
        let x: f64 = iter.next().unwrap().parse().unwrap();
        let y: f64 = iter.next().unwrap().parse().unwrap();
        points.push((x, y));
    }

    const LIMIT: usize = 30;
    let max_skips = LIMIT.min(n - 2);
    let mut dp = vec![vec![f64::INFINITY; max_skips + 1]; n];
    dp[0][0] = 0.0;

    for i in 1..n {
        let max_immediate_skips = max_skips.min(i - 1);

        for skipped_now in 0..=max_immediate_skips {
            let previous = i - skipped_now - 1;
            let dx = points[i].0 - points[previous].0;
            let dy = points[i].1 - points[previous].1;
            let distance = dx.hypot(dy);

            for previous_skips in 0..=max_skips - skipped_now {
                let previous_cost = dp[previous][previous_skips];
                if previous_cost.is_finite() {
                    let total_skips = previous_skips + skipped_now;
                    let candidate = previous_cost + distance;
                    if candidate < dp[i][total_skips] {
                        dp[i][total_skips] = candidate;
                    }
                }
            }
        }
    }

    let mut answer = f64::INFINITY;

    for skipped in 0..=max_skips {
        let penalty = if skipped == 0 {
            0.0
        } else {
            (1u64 << (skipped - 1)) as f64
        };
        answer = answer.min(dp[n - 1][skipped] + penalty);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{:.15}", answer).unwrap();
}
