use std::io::{self, Read, Write};

fn solve(mask: usize, n: usize, weights: &[Vec<i64>], memo: &mut [i64]) -> i64 {
    let full_mask = (1usize << n) - 1;
    if mask == full_mask {
        return 0;
    }
    if memo[mask] != -1 {
        return memo[mask];
    }

    let first = (0..n).find(|&i| mask & (1usize << i) == 0).unwrap();
    let mask_with_first = mask | (1usize << first);
    let mut best = 0i64;

    for second in first + 1..n {
        if mask_with_first & (1usize << second) == 0 {
            let next_mask = mask_with_first | (1usize << second);
            best = best.max(weights[first][second] + solve(next_mask, n, weights, memo));
        }
    }

    memo[mask] = best;
    best
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let original_n: usize = iter.next().unwrap().parse().unwrap();
    let n = if original_n % 2 == 0 {
        original_n
    } else {
        original_n + 1
    };

    let mut weights = vec![vec![0i64; n]; n];
    for i in 0..original_n {
        for j in i + 1..original_n {
            let weight: i64 = iter.next().unwrap().parse().unwrap();
            weights[i][j] = weight;
            weights[j][i] = weight;
        }
    }

    let mut memo = vec![-1i64; 1usize << n];
    let answer = solve(0, n, &weights, &mut memo);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
