use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut graph = vec![Vec::new(); n];

    for _ in 0..n - 1 {
        let u: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let v: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        graph[u].push(v);
        graph[v].push(u);
    }

    let mut parent = vec![n; n];
    let mut order = Vec::with_capacity(n);
    let mut stack = vec![0usize];
    parent[0] = 0;

    while let Some(v) = stack.pop() {
        order.push(v);
        for &next in &graph[v] {
            if next != parent[v] {
                parent[next] = v;
                stack.push(next);
            }
        }
    }

    let mut subtree_size = vec![1usize; n];
    for &v in order.iter().rev() {
        if v != 0 {
            subtree_size[parent[v]] += subtree_size[v];
        }
    }

    let largest_component = graph[0]
        .iter()
        .map(|&child| subtree_size[child])
        .max()
        .unwrap_or(0);

    let answer = n - largest_component;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
