use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let q: usize = iter.next().unwrap().parse().unwrap();

    let mut history: Vec<(i32, i32)> = Vec::with_capacity(q + 1);
    history.push((1, 0));

    let mut moves = 0usize;
    let mut output = String::new();

    for _ in 0..q {
        let query_type: u8 = iter.next().unwrap().parse().unwrap();

        if query_type == 1 {
            let direction = iter.next().unwrap().as_bytes()[0];
            let (mut x, mut y) = history[moves];

            match direction {
                b'R' => x += 1,
                b'L' => x -= 1,
                b'U' => y += 1,
                b'D' => y -= 1,
                _ => unreachable!(),
            }

            history.push((x, y));
            moves += 1;
        } else {
            let p: usize = iter.next().unwrap().parse().unwrap();

            let (x, y) = if p <= moves + 1 {
                history[moves + 1 - p]
            } else {
                ((p - moves) as i32, 0)
            };

            output.push_str(&format!("{} {}\n", x, y));
        }
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();

    let _ = n;
}
