use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();

    const INF: i32 = 1_000_000_000;
    let mut dist = vec![INF; n * n];

    for i in 0..n {
        dist[i * n + i] = 0;
    }

    for _ in 0..m {
        let u: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let v: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let w: i32 = it.next().unwrap().parse().unwrap();
        dist[u * n + v] = w;
    }

    for k in 0..n {
        for i in 0..n {
            let dik = dist[i * n + k];
            if dik == INF {
                continue;
            }
            for j in 0..n {
                let dkj = dist[k * n + j];
                if dkj == INF {
                    continue;
                }
                let candidate = dik + dkj;
                let index = i * n + j;
                if candidate < dist[index] {
                    dist[index] = candidate;
                }
            }
        }
    }

    let states = 1usize << n;
    let mut dp = vec![INF; states * n];

    for v in 0..n {
        dp[((1usize << v) * n) + v] = 0;
    }

    for mask in 1usize..states {
        if mask.is_power_of_two() {
            continue;
        }

        let mut ends = mask;
        while ends != 0 {
            let v = ends.trailing_zeros() as usize;
            ends &= ends - 1;

            let previous_mask = mask ^ (1usize << v);
            let previous_base = previous_mask * n;
            let mut previous_vertices = previous_mask;
            let mut best = INF;

            while previous_vertices != 0 {
                let u = previous_vertices.trailing_zeros() as usize;
                previous_vertices &= previous_vertices - 1;

                let current = dp[previous_base + u];
                let d = dist[u * n + v];
                if current != INF && d != INF {
                    best = best.min(current + d);
                }
            }

            dp[mask * n + v] = best;
        }
    }

    let full_base = (states - 1) * n;
    let answer = (0..n).map(|v| dp[full_base + v]).min().unwrap();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    if answer == INF {
        writeln!(out, "No").unwrap();
    } else {
        writeln!(out, "{answer}").unwrap();
    }
}
