use std::io::{self, Read, Write};

#[derive(Clone, Copy)]
struct Node {
    prev: Option<i64>,
    next: Option<i64>,
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut values = Vec::with_capacity(n);

    for _ in 0..n {
        values.push(iter.next().unwrap().parse::<i64>().unwrap());
    }

    let mut nodes: HashMap<i64, Node> = HashMap::with_capacity(n * 2);
    for i in 0..n {
        nodes.insert(
            values[i],
            Node {
                prev: if i > 0 { Some(values[i - 1]) } else { None },
                next: if i + 1 < n {
                    Some(values[i + 1])
                } else {
                    None
                },
            },
        );
    }

    let mut head = Some(values[0]);
    let q: usize = iter.next().unwrap().parse().unwrap();

    for _ in 0..q {
        let query_type: u8 = iter.next().unwrap().parse().unwrap();

        if query_type == 1 {
            let x: i64 = iter.next().unwrap().parse().unwrap();
            let y: i64 = iter.next().unwrap().parse().unwrap();

            let next = nodes.get(&x).unwrap().next;

            nodes.insert(
                y,
                Node {
                    prev: Some(x),
                    next,
                },
            );
            nodes.get_mut(&x).unwrap().next = Some(y);

            if let Some(next_value) = next {
                nodes.get_mut(&next_value).unwrap().prev = Some(y);
            }
        } else {
            let x: i64 = iter.next().unwrap().parse().unwrap();
            let node = *nodes.get(&x).unwrap();

            if let Some(prev_value) = node.prev {
                nodes.get_mut(&prev_value).unwrap().next = node.next;
            } else {
                head = node.next;
            }

            if let Some(next_value) = node.next {
                nodes.get_mut(&next_value).unwrap().prev = node.prev;
            }

            nodes.remove(&x);
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    let mut current = head;
    let mut first = true;

    while let Some(value) = current {
        if !first {
            write!(out, " ").unwrap();
        }
        first = false;
        write!(out, "{}", value).unwrap();
        current = nodes.get(&value).unwrap().next;
    }

    writeln!(out).unwrap();
}
