use std::io::{self, Read, Write};

fn prefix(x: i128, y: i128) -> i128 {
    const PATTERN: [[i128; 4]; 2] = [
        [2, 1, 0, 1],
        [1, 2, 1, 0],
    ];

    let qx = x.div_euclid(4);
    let rx = x.rem_euclid(4) as usize;
    let qy = y.div_euclid(2);
    let ry = y.rem_euclid(2) as usize;

    let mut result = qx * qy * 8;
    result += qx * (ry as i128) * 4;

    let mut full_rows_partial_columns = 0;
    for row in &PATTERN {
        for col in 0..rx {
            full_rows_partial_columns += row[col];
        }
    }
    result += qy * full_rows_partial_columns;

    for row in 0..ry {
        for col in 0..rx {
            result += PATTERN[row][col];
        }
    }

    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace().map(|s| s.parse::<i128>().unwrap());

    let a = it.next().unwrap();
    let b = it.next().unwrap();
    let c = it.next().unwrap();
    let d = it.next().unwrap();

    let answer = prefix(c, d) - prefix(a, d) - prefix(c, b) + prefix(a, b);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
