    right.sort_unstable();

    // Two closed intervals are disjoint exactly when one ends strictly
    // before the other starts.
    let mut ended = 0usize;
    let mut disjoint_pairs = 0i64;

    for &l in &left {
        while ended < n && right[ended] < l {
            ended += 1;
        }
        disjoint_pairs += ended as i64;
    }

    let total_pairs = (n as i64) * ((n - 1) as i64) / 2;
    let answer = total_pairs - disjoint_pairs;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
