use std::io::{self, Read, Write};

const MOD: u64 = 998_244_353;

fn mod_pow(mut base: u64, mut exp: u64) -> u64 {
    let mut result = 1u64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1;
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let s = input.trim();
    let n: u64 = s.parse().unwrap();
    let digits = s.len() as u64;

    let q = mod_pow(10, digits);

    // Compute 1 + q + q^2 + ... + q^(n-1) modulo MOD.
    let mut exp = n;
    let mut result_pow = 1u64;
    let mut result_sum = 0u64;
    let mut block_pow = q;
    let mut block_sum = 1u64;

    while exp > 0 {
        if exp & 1 == 1 {
            result_sum = (result_sum + result_pow * block_sum) % MOD;
            result_pow = result_pow * block_pow % MOD;
        }

        block_sum = (block_sum + block_pow * block_sum) % MOD;
        block_pow = block_pow * block_pow % MOD;
        exp >>= 1;
    }

    let answer = (n % MOD) * result_sum % MOD;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
