use std::io::{self, Read, Write};

const MOD: u64 = 998_244_353;

fn mod_pow(mut base: u64, mut exp: u64) -> u64 {
    let mut result = 1u64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1;
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let k: usize = iter.next().unwrap().parse().unwrap();
    let limits: Vec<usize> = (0..26)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let mut factorial = vec![1u64; k + 1];
    for i in 1..=k {
        factorial[i] = factorial[i - 1] * i as u64 % MOD;
    }

    let mut inv_factorial = vec![1u64; k + 1];
    inv_factorial[k] = mod_pow(factorial[k], MOD - 2);
    for i in (1..=k).rev() {
        inv_factorial[i - 1] = inv_factorial[i] * i as u64 % MOD;
    }

    // dp[n] is the coefficient of x^n in the product of
    // sum_{j=0}^{C_i} x^j / j! for the processed letters.
    let mut dp = vec![0u64; k + 1];
    dp[0] = 1;

    for limit in limits {
        let limit = limit.min(k);
        let mut next = vec![0u64; k + 1];

        for total in 0..=k {
            let max_add = limit.min(total);
            let mut value = 0u64;

            for add in 0..=max_add {
                value += dp[total - add] * inv_factorial[add] % MOD;
                if value >= MOD {
                    value -= MOD;
                }
            }
            next[total] = value;
        }

        dp = next;
    }

    let mut answer = 0u64;
    for length in 1..=k {
        answer += dp[length] * factorial[length] % MOD;
        if answer >= MOD {
            answer -= MOD;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
