use std::io::{self, Read, Write};

fn farthest(start: usize, graph: &[Vec<(usize, i64)>]) -> (usize, i64) {
    let mut stack = vec![(start, usize::MAX, 0_i64)];
    let mut result = (start, 0_i64);

    while let Some((node, parent, distance)) = stack.pop() {
        if distance > result.1 {
            result = (node, distance);
        }

        for &(next, weight) in &graph[node] {
            if next != parent {
                stack.push((next, node, distance + weight));
            }
        }
    }

    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut graph = vec![Vec::<(usize, i64)>::new(); n];
    let mut total_weight = 0_i64;

    for _ in 0..n - 1 {
        let a: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let b: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let c: i64 = iter.next().unwrap().parse().unwrap();

        graph[a].push((b, c));
        graph[b].push((a, c));
        total_weight += c;
    }

    let (endpoint, _) = farthest(0, &graph);
    let (_, diameter) = farthest(endpoint, &graph);
    let answer = 2 * total_weight - diameter;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
