    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let a: Vec<i64> = (0..n)
        .map(|_| it.next().unwrap().parse().unwrap())
        .collect();

    let lengths = n + 1;
    let mut dp = vec![0_u64; n * n * lengths];
    let mut answer = vec![0_u64; n + 1];
    answer[1] = n as u64 % MOD;

    for i in 0..n {
        for j in (i + 1)..n {
            let dst_base = (i * n + j) * lengths;
            dp[dst_base + 2] = 1;
            answer[2] += 1;
            if answer[2] >= MOD {
                answer[2] -= MOD;
            }

            let difference = a[j] - a[i];

            for h in 0..i {
                if a[i] - a[h] != difference {
                    continue;
                }

                let src_base = (h * n + i) * lengths;
                for len in 2..=(h + 2) {
                    let value = dp[src_base + len];
                    if value == 0 {
                        continue;
                    }

                    let dst = dst_base + len + 1;
                    dp[dst] += value;
                    if dp[dst] >= MOD {
                        dp[dst] -= MOD;
                    }

                    answer[len + 1] += value;
                    if answer[len + 1] >= MOD {
                        answer[len + 1] -= MOD;
                    }
                }
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for k in 1..=n {
        if k > 1 {
            write!(out, " ").unwrap();
        }
        write!(out, "{}", answer[k]).unwrap();
    }
    writeln!(out).unwrap();
