use std::io::{self, Read, Write};

struct Dsu {
    parent: Vec<usize>,
    size: Vec<usize>,
}

impl Dsu {
    fn new(n: usize) -> Self {
        Self {
            parent: (0..n).collect(),
            size: vec![1; n],
        }
    }

    fn find(&mut self, mut x: usize) -> usize {
        let mut root = x;
        while self.parent[root] != root {
            root = self.parent[root];
        }
        while self.parent[x] != x {
            let next = self.parent[x];
            self.parent[x] = root;
            x = next;
        }
        root
    }

    fn unite(&mut self, a: usize, b: usize) -> bool {
        let mut ra = self.find(a);
        let mut rb = self.find(b);
        if ra == rb {
            return false;
        }
        if self.size[ra] < self.size[rb] {
            std::mem::swap(&mut ra, &mut rb);
        }
        self.parent[rb] = ra;
        self.size[ra] += self.size[rb];
        true
    }
}

struct Successor {
    parent: Vec<usize>,
}

impl Successor {
    fn new(n: usize) -> Self {
        Self {
            parent: (0..n).collect(),
        }
    }

    fn find(&mut self, mut x: usize) -> usize {
        let mut root = x;
        while self.parent[root] != root {
            root = self.parent[root];
        }
        while self.parent[x] != x {
            let next = self.parent[x];
            self.parent[x] = root;
            x = next;
        }
        root
    }

    fn erase(&mut self, x: usize) {
        let next = self.find(x + 1);
        self.parent[x] = next;
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let q: usize = it.next().unwrap().parse().unwrap();

    let mut queries = Vec::with_capacity(q);
    for id in 0..q {
        let l: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let r: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let c: i64 = it.next().unwrap().parse().unwrap();
        queries.push((c, l, r, id));
    }

    queries.sort_unstable_by_key(|&(c, _, _, _)| c);

    let mut dsu = Dsu::new(n + q);
    let mut successor = Successor::new(n);
    let mut total_cost = 0_i64;
    let mut used_edges = 0_usize;

    for (cost, l, r, id) in queries {
        let query_vertex = n + id;

        if dsu.unite(query_vertex, l) {
            total_cost += cost;
            used_edges += 1;
        }

        let mut boundary = successor.find(l);
        while boundary < r {
            if dsu.unite(query_vertex, boundary + 1) {
                total_cost += cost;
                used_edges += 1;
            }
            successor.erase(boundary);
            boundary = successor.find(boundary);
        }
    }

    let answer = if used_edges == n + q - 1 {
        total_cost
    } else {
        -1
    };

