use std::io::{self, Read, Write};

fn lower_bound(values: &[i64], target: i64) -> usize {
    let mut left = 0usize;
    let mut right = values.len();
    while left < right {
        let mid = left + (right - left) / 2;
        if values[mid] < target {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    left
}

fn upper_bound(values: &[i64], target: i64) -> usize {
    let mut left = 0usize;
    let mut right = values.len();
    while left < right {
        let mid = left + (right - left) / 2;
        if values[mid] <= target {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    left
}

fn cost_frequencies(mut coordinates: Vec<i64>, d: usize) -> Option<Vec<i64>> {
    coordinates.sort_unstable();

    let n = coordinates.len();
    let median = coordinates[n / 2];
    let min_cost: i64 = coordinates.iter().map(|&v| (v - median).abs()).sum();

    if min_cost > d as i64 {
        return None;
    }

    let mut frequencies = vec![0i64; d + 1];

    // Enumerate the median and all feasible positions to its right.
    let mut position = median;
    let mut cost = min_cost;
    let mut count_le = upper_bound(&coordinates, position);

    loop {
        if cost > d as i64 {
            break;
        }
        frequencies[cost as usize] += 1;

        let slope = 2 * count_le as i64 - n as i64;
        cost += slope;
        position += 1;

        while count_le < n && coordinates[count_le] <= position {
            count_le += 1;
        }
    }

    // Enumerate feasible positions strictly to the left of the median.
    position = median;
    cost = min_cost;
    let mut count_lt = lower_bound(&coordinates, position);

    loop {
        let increase = n as i64 - 2 * count_lt as i64;
        cost += increase;
        position -= 1;

        while count_lt > 0 && coordinates[count_lt - 1] >= position {
            count_lt -= 1;
        }

        if cost > d as i64 {
            break;
        }
        frequencies[cost as usize] += 1;
    }

    Some(frequencies)
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let d: usize = iter.next().unwrap().parse().unwrap();

    let mut xs = Vec::with_capacity(n);
    let mut ys = Vec::with_capacity(n);

    for _ in 0..n {
        let x: i64 = iter.next().unwrap().parse().unwrap();
        let y: i64 = iter.next().unwrap().parse().unwrap();
        xs.push(x);
        ys.push(y);
    }

    let Some(x_frequencies) = cost_frequencies(xs, d) else {
        println!("0");
        return;
    };
    let Some(mut y_prefix) = cost_frequencies(ys, d) else {
        println!("0");
        return;
    };

    for cost in 1..=d {
        y_prefix[cost] += y_prefix[cost - 1];
    }

    let mut answer = 0i64;
    for x_cost in 0..=d {
        answer += x_frequencies[x_cost] * y_prefix[d - x_cost];
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
