use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();

    const INF: i64 = i64::MAX / 4;
    let mut dist = vec![INF; n * n];
    for i in 0..n {
        dist[i * n + i] = 0;
    }

    let mut bridges = Vec::with_capacity(m);
    for _ in 0..m {
        let u: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let v: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let t: i64 = it.next().unwrap().parse().unwrap();

        bridges.push((u, v, t));
        let uv = u * n + v;
        let vu = v * n + u;
        if t < dist[uv] {
            dist[uv] = t;
            dist[vu] = t;
        }
    }

    for k in 0..n {
        let row_k = dist[k * n..(k + 1) * n].to_vec();
        for row_i in dist.chunks_mut(n) {
            let dik = row_i[k];
            if dik == INF {
                continue;
            }
            for j in 0..n {
                let nd = dik + row_k[j];
                if nd < row_i[j] {
                    row_i[j] = nd;
                }
            }
        }
    }

    let q: usize = it.next().unwrap().parse().unwrap();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for _ in 0..q {
        let k: usize = it.next().unwrap().parse().unwrap();
        let mut required = Vec::with_capacity(k);
        for _ in 0..k {
            let b: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
            required.push(bridges[b]);
        }

        let states = 1usize << k;
        let mut dp = vec![INF; states * k * 2];

        for i in 0..k {
            let (u, v, t) = required[i];

            // End at u after crossing v -> u.
            dp[((1usize << i) * k + i) * 2] = dist[v] + t;

            // End at v after crossing u -> v.
            dp[((1usize << i) * k + i) * 2 + 1] = dist[u] + t;
        }

        for mask in 1..states {
            for last in 0..k {
                if mask & (1usize << last) == 0 {
                    continue;
                }

                let (last_u, last_v, _) = required[last];
                for side in 0..2 {
                    let current = dp[(mask * k + last) * 2 + side];
                    if current == INF {
                        continue;
                    }

                    let current_island = if side == 0 { last_u } else { last_v };

                    for next in 0..k {
                        if mask & (1usize << next) != 0 {
                            continue;
                        }

                        let (u, v, t) = required[next];
                        let next_mask = mask | (1usize << next);

                        // Cross v -> u and end at u.
                        let cost_to_u = current + dist[current_island * n + v] + t;
                        let idx_u = (next_mask * k + next) * 2;
                        if cost_to_u < dp[idx_u] {
                            dp[idx_u] = cost_to_u;
                        }

                        // Cross u -> v and end at v.
                        let cost_to_v = current + dist[current_island * n + u] + t;
                        let idx_v = idx_u + 1;
                        if cost_to_v < dp[idx_v] {
                            dp[idx_v] = cost_to_v;
                        }
                    }
                }
            }
        }

        let full = states - 1;
        let mut answer = INF;
        for last in 0..k {
            let (u, v, _) = required[last];

            let end_u = dp[(full * k + last) * 2] + dist[u * n + (n - 1)];
            answer = answer.min(end_u);

            let end_v = dp[(full * k + last) * 2 + 1] + dist[v * n + (n - 1)];
            answer = answer.min(end_v);
        }

        writeln!(out, "{answer}").unwrap();
    }
}
