use std::io::{self, Read, Write};

fn next_permutation(a: &mut [usize]) -> bool {
    if a.len() < 2 {
        return false;
    }

    let mut i = a.len() - 2;
    loop {
        if a[i] < a[i + 1] {
            break;
        }
        if i == 0 {
            return false;
        }
        i -= 1;
    }

    let mut j = a.len() - 1;
    while a[j] <= a[i] {
        j -= 1;
    }

    a.swap(i, j);
    a[i + 1..].reverse();
    true
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();

    let mut g = vec![vec![false; n]; n];
    let mg: usize = iter.next().unwrap().parse().unwrap();
    for _ in 0..mg {
        let u: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let v: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        g[u][v] = true;
        g[v][u] = true;
    }

    let mut h = vec![vec![false; n]; n];
    let mh: usize = iter.next().unwrap().parse().unwrap();
    for _ in 0..mh {
        let a: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let b: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        h[a][b] = true;
        h[b][a] = true;
    }

    let mut cost = vec![vec![0_i64; n]; n];
    for i in 0..n {
        for j in i + 1..n {
            let value: i64 = iter.next().unwrap().parse().unwrap();
            cost[i][j] = value;
            cost[j][i] = value;
        }
    }

    let mut permutation: Vec<usize> = (0..n).collect();
    let mut answer = i64::MAX;

    loop {
        let mut current = 0_i64;

        for i in 0..n {
            for j in i + 1..n {
                let pi = permutation[i];
                let pj = permutation[j];
                if g[i][j] != h[pi][pj] {
                    current += cost[pi][pj];
                }
            }
        }

        answer = answer.min(current);

        if !next_permutation(&mut permutation) {
            break;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
