use std::io::{self, Read, Write};

struct Dsu {
    parent: Vec<usize>,
    size: Vec<usize>,
    largest: Vec<Vec<usize>>,
}

impl Dsu {
    fn new(n: usize) -> Self {
        let mut largest = Vec::with_capacity(n);
        for i in 0..n {
            largest.push(vec![i + 1]);
        }

        Self {
            parent: (0..n).collect(),
            size: vec![1; n],
            largest,
        }
    }

    fn find(&mut self, x: usize) -> usize {
        if self.parent[x] != x {
            self.parent[x] = self.find(self.parent[x]);
        }
        self.parent[x]
    }

    fn unite(&mut self, a: usize, b: usize) {
        let mut ra = self.find(a);
        let mut rb = self.find(b);

        if ra == rb {
            return;
        }

        if self.size[ra] < self.size[rb] {
            std::mem::swap(&mut ra, &mut rb);
        }

        self.parent[rb] = ra;
        self.size[ra] += self.size[rb];

        let a_values = self.largest[ra].clone();
        let b_values = self.largest[rb].clone();
        let mut merged = Vec::with_capacity(10);
        let (mut i, mut j) = (0, 0);

        while merged.len() < 10 && (i < a_values.len() || j < b_values.len()) {
            if j == b_values.len()
                || (i < a_values.len() && a_values[i] > b_values[j])
            {
                merged.push(a_values[i]);
                i += 1;
            } else {
                merged.push(b_values[j]);
                j += 1;
            }
        }

        self.largest[ra] = merged;
        self.largest[rb].clear();
    }

    fn kth_largest(&mut self, v: usize, k: usize) -> Option<usize> {
        let root = self.find(v);
        self.largest[root].get(k - 1).copied()
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let q: usize = iter.next().unwrap().parse().unwrap();

    let mut dsu = Dsu::new(n);
    let mut output = String::new();

    for _ in 0..q {
        let query_type: usize = iter.next().unwrap().parse().unwrap();
        let x: usize = iter.next().unwrap().parse().unwrap();
        let y: usize = iter.next().unwrap().parse().unwrap();

        if query_type == 1 {
            dsu.unite(x - 1, y - 1);
        } else {
            match dsu.kth_largest(x - 1, y) {
                Some(answer) => {
                    output.push_str(&answer.to_string());
                    output.push('\n');
                }
                None => output.push_str("-1\n"),
            }
        }
    }

    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    writer.write_all(output.as_bytes()).unwrap();
}
