use std::collections::BinaryHeap;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let t: usize = iter.next().unwrap().parse().unwrap();
    let mut output = io::BufWriter::new(io::stdout().lock());

    for _ in 0..t {
        let n: usize = iter.next().unwrap().parse().unwrap();
        let k: usize = iter.next().unwrap().parse().unwrap();

        let mut a = Vec::with_capacity(n);
        for _ in 0..n {
            a.push(iter.next().unwrap().parse::<i64>().unwrap());
        }

        let mut pairs = Vec::with_capacity(n);
        for ai in a {
            let bi: i64 = iter.next().unwrap().parse().unwrap();
            pairs.push((ai, bi));
        }

        pairs.sort_unstable_by_key(|&(ai, _)| ai);

        let mut heap = BinaryHeap::with_capacity(k + 1);
        let mut sum_b = 0_i64;
        let mut answer = i64::MAX;

        for (ai, bi) in pairs {
            heap.push(bi);
            sum_b += bi;

            if heap.len() > k {
                sum_b -= heap.pop().unwrap();
            }

            if heap.len() == k {
                answer = answer.min(ai * sum_b);
            }
        }

        writeln!(output, "{answer}").unwrap();
    }
