use std::io::{self, Read, Write};

struct Dsu {
    parent: Vec<usize>,
    size: Vec<usize>,
}

impl Dsu {
    fn new(n: usize) -> Self {
        Self {
            parent: (0..n).collect(),
            size: vec![1; n],
        }
    }

    fn find(&mut self, x: usize) -> usize {
        let mut root = x;
        while self.parent[root] != root {
            root = self.parent[root];
        }
        let mut cur = x;
        while self.parent[cur] != cur {
            let next = self.parent[cur];
            self.parent[cur] = root;
            cur = next;
        }
        root
    }

    fn unite(&mut self, a: usize, b: usize) {
        let mut x = self.find(a);
        let mut y = self.find(b);
        if x == y {
            return;
        }
        if self.size[x] < self.size[y] {
            std::mem::swap(&mut x, &mut y);
        }
        self.parent[y] = x;
        self.size[x] += self.size[y];
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut edges = Vec::with_capacity(n - 1);
    let mut degree = vec![0usize; n];

    for _ in 0..n - 1 {
        let u: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let v: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        edges.push((u, v));
        degree[u] += 1;
        degree[v] += 1;
    }

    let mut dsu = Dsu::new(n);

    for &(u, v) in &edges {
        if degree[u] == 3 && degree[v] == 3 {
            dsu.unite(u, v);
        }
    }

    let mut attached_degree_two = vec![0i64; n];

    for &(u, v) in &edges {
        if degree[u] == 2 && degree[v] == 3 {
            let root = dsu.find(v);
            attached_degree_two[root] += 1;
        } else if degree[u] == 3 && degree[v] == 2 {
            let root = dsu.find(u);
            attached_degree_two[root] += 1;
        }
    }

    let mut answer = 0i64;
    for count in attached_degree_two {
        answer += count * (count - 1) / 2;
