fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let h: usize = iter.next().unwrap().parse().unwrap();
    let w: usize = iter.next().unwrap().parse().unwrap();
    let d: i32 = iter.next().unwrap().parse().unwrap();

    let mut grid = Vec::with_capacity(h * w);
    for _ in 0..h {
        grid.extend_from_slice(iter.next().unwrap().as_bytes());
    }

    let mut distance = vec![-1_i32; h * w];
    let mut queue = VecDeque::new();
    let mut answer = 0_usize;

    for index in 0..h * w {
        if grid[index] == b'H' {
            distance[index] = 0;
            queue.push_back(index);
            answer += 1;
        }
    }

    while let Some(index) = queue.pop_front() {
        let current_distance = distance[index];
        if current_distance == d {
            continue;
        }

        let row = index / w;
        let col = index % w;

        if row > 0 {
            let next = index - w;
            if grid[next] != b'#' && distance[next] == -1 {
                distance[next] = current_distance + 1;
                queue.push_back(next);
                answer += 1;
            }
        }
        if row + 1 < h {
            let next = index + w;
            if grid[next] != b'#' && distance[next] == -1 {
                distance[next] = current_distance + 1;
                queue.push_back(next);
                answer += 1;
            }
        }
        if col > 0 {
            let next = index - 1;
            if grid[next] != b'#' && distance[next] == -1 {
                distance[next] = current_distance + 1;
                queue.push_back(next);
                answer += 1;
            }
        }
        if col + 1 < w {
            let next = index + 1;
            if grid[next] != b'#' && distance[next] == -1 {
                distance[next] = current_distance + 1;
                queue.push_back(next);
                answer += 1;
            }
        }
    }

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    writeln!(output, "{answer}").unwrap();
}
