        .map(|_| iter.next().unwrap().as_bytes().to_vec())
        .collect();
    let moves = iter.next().unwrap().as_bytes();

    let mut visited = vec![vec![false; w]; h];
    let mut houses = 0;

    for &direction in moves {
        let (nx, ny) = match direction {
            b'U' => (x - 1, y),
            b'D' => (x + 1, y),
            b'L' => (x, y - 1),
            b'R' => (x, y + 1),
            _ => unreachable!(),
        };

        if grid[nx][ny] != b'#' {
            x = nx;
            y = ny;

            if grid[x][y] == b'@' && !visited[x][y] {
                visited[x][y] = true;
                houses += 1;
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{} {} {}", x + 1, y + 1, houses).unwrap();
