use std::io::{self, Read, Write};

fn enumerate(
    a: &[u64],
    start: usize,
    remaining: usize,
    current_xor: u64,
    base_xor: u64,
    answer: &mut u64,
) {
    if remaining == 0 {
        *answer = (*answer).max(base_xor ^ current_xor);
        return;
    }

    let last = a.len() - remaining;
    for i in start..=last {
        enumerate(
            a,
            i + 1,
            remaining - 1,
            current_xor ^ a[i],
            base_xor,
            answer,
        );
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();

    let mut a = Vec::with_capacity(n);
    let mut total_xor = 0u64;

    for _ in 0..n {
        let value: u64 = iter.next().unwrap().parse().unwrap();
        a.push(value);
        total_xor ^= value;
    }

    let (choose, base_xor) = if k <= n - k {
        (k, 0)
    } else {
        (n - k, total_xor)
    };

    let mut answer = 0u64;
    enumerate(&a, 0, choose, 0, base_xor, &mut answer);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
