use std::io::{self, Read, Write};

const MOD: i64 = 998_244_353;

fn mod_pow(mut base: i64, mut exp: usize) -> i64 {
    let mut result = 1_i64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1;
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let _n: usize = it.next().unwrap().parse().unwrap();
    let q: usize = it.next().unwrap().parse().unwrap();

    let mut p = Vec::with_capacity(q);
    let mut v = Vec::with_capacity(q);

    for _ in 0..q {
        p.push(it.next().unwrap().parse::<usize>().unwrap());
        v.push(it.next().unwrap().parse::<i64>().unwrap());
    }

    // -1: not forced, 0: prefix, 1: suffix
    let mut forced = vec![-1_i8; q];

    for i in 0..q {
        for j in 0..i {
            if v[j] <= v[i] {
                continue;
            }

            if p[j] == p[i] {
                let stdout = io::stdout();
                let mut out = io::BufWriter::new(stdout.lock());
                writeln!(out, "0").unwrap();
                return;
            }

            let (need_j, need_i) = if p[j] < p[i] {
                (0_i8, 1_i8)
            } else {
                (1_i8, 0_i8)
            };

            if (forced[j] != -1 && forced[j] != need_j)
                || (forced[i] != -1 && forced[i] != need_i)
            {
                let stdout = io::stdout();
                let mut out = io::BufWriter::new(stdout.lock());
                writeln!(out, "0").unwrap();
                return;
            }

            forced[j] = need_j;
            forced[i] = need_i;
        }
    }

    let free = forced.iter().filter(|&&x| x == -1).count();
    let answer = mod_pow(2, free);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
