use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();
    let n: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();

    let mut answer = Vec::with_capacity(n * k);

    if n % 2 == 0 {
        let lower_middle = n / 2;
        answer.push(lower_middle);

        for value in (1..=n).rev() {
            let count = if value == lower_middle { k - 1 } else { k };
            for _ in 0..count {
                answer.push(value);
            }
        }
    } else {
        let middle = (n + 1) / 2;

        for _ in 0..k {
            answer.push(middle);
        }

        if n > 1 {
            let lower_middle = middle - 1;
            answer.push(lower_middle);

            for value in (1..=n).rev() {
                let count = if value == middle {
                    0
                } else if value == lower_middle {
                    k - 1
                } else {
                    k
                };

                for _ in 0..count {
                    answer.push(value);
                }
            }
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for (i, value) in answer.iter().enumerate() {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{value}").unwrap();
    }
    writeln!(out).unwrap();
}
