use std::collections::HashSet;
use std::io::{self, Read, Write};

fn is_mountain(x: u128) -> bool {
    let odd_part = x >> x.trailing_zeros();
    odd_part & 3 == 3
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let a: Vec<u128> = (0..n)
        .map(|_| iter.next().unwrap().parse::<u128>().unwrap())
        .collect();

    let mut candidates = HashSet::with_capacity(n * 128);

    for &value in &a {
        for t in 0..=60u32 {
            let modulus = 1u128 << t;
            let rem = value % modulus;
            let r = if rem == 0 { 0 } else { modulus - rem };
            let base_quotient = (r + value) >> t;

            for target in [1u128, 3u128] {
                let q = (target + 4 - (base_quotient & 3)) & 3;
                let mut i = r + q * modulus;

                if i == 0 {
                    i += 4 * modulus;
                }
                candidates.insert(i);
            }
        }
    }

    let mut answer = 0usize;

    for i in candidates {
        let mut count = 0usize;
        for &offset in &a {
            if is_mountain(i + offset) {
                count += 1;
            }
        }
        answer = answer.max(count);
        if answer == n {
            break;
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
