use std::io::{self, Read, Write};

const MOD: u64 = 998_244_353;

fn mod_pow(mut base: u64, mut exp: u64) -> u64 {
    let mut result = 1u64;
    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1;
    }
    result
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut a = vec![0usize; n + 1];
    for i in 1..=n {
        a[i] = iter.next().unwrap().parse().unwrap();
    }

    let mut last_child = vec![0usize; n + 1];
    let mut parent = vec![0usize; n + 1];

    for i in 1..=n {
        let p = a[i];
        if last_child[p] != 0 {
            parent[last_child[p]] = i;
        }
        last_child[p] = i;
    }

    for p in 1..=n {
        if last_child[p] != 0 {
            parent[last_child[p]] = p;
        }
    }

    let mut remaining_children = vec![0usize; n + 1];
    for v in 1..=n {
        if parent[v] != 0 {
            remaining_children[parent[v]] += 1;
        }
    }

    let mut stack = Vec::with_capacity(n);
    for v in 1..=n {
        if remaining_children[v] == 0 {
            stack.push(v);
        }
    }

    let mut subtree_size = vec![1usize; n + 1];
    let mut hook_product = 1u64;

    while let Some(v) = stack.pop() {
        hook_product = hook_product * subtree_size[v] as u64 % MOD;

        let p = parent[v];
        if p != 0 {
            subtree_size[p] += subtree_size[v];
            remaining_children[p] -= 1;
            if remaining_children[p] == 0 {
                stack.push(p);
            }
        }
    }

    let mut factorial = 1u64;
    for i in 1..=n {
        factorial = factorial * i as u64 % MOD;
    }

    let answer = factorial * mod_pow(hook_product, MOD - 2) % MOD;

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
