use std::io::{self, Read, Write};

const MOD: u64 = 998_244_353;

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();
    let k: usize = it.next().unwrap().parse().unwrap();
    let x: Vec<usize> = (0..m)
        .map(|_| it.next().unwrap().parse().unwrap())
        .collect();

    let q = k - 1;
    let target = n - (m - 1);

    let mut factors = Vec::with_capacity(m);
    let mut changes = 0usize;

    for i in 0..m - 1 {
        let changed = x[i] != x[i + 1];
        if changed {
            changes += 1;
        }
        factors.push(changed);
    }
    factors.push(false);

    let minimum_total = m * q + changes;
    if target < minimum_total {
        let mut out = io::BufWriter::new(io::stdout().lock());
        writeln!(out, "0").unwrap();
        return;
    }

    // surjective[len]: number of length-len words over q symbols
    // in which every symbol occurs.
    let mut surjective = vec![0u64; target + 1];
    let mut used_dp = vec![0u64; q + 1];
    used_dp[0] = 1;

    for len in 1..=target {
        let mut next = vec![0u64; q + 1];
        let max_used = q.min(len);

        for used in 1..=max_used {
            let existing = used_dp[used] * used as u64 % MOD;
            let new_symbol =
                used_dp[used - 1] * (q - used + 1) as u64 % MOD;
            let sum = existing + new_symbol;
            next[used] = if sum >= MOD { sum - MOD } else { sum };
        }

        used_dp = next;
        surjective[len] = used_dp[q];
    }

    // changed[len] counts valid blocks when x_i != x_{i+1}.
    // Such a block has a distinguished symbol whose last occurrence
    // comes after the first occurrence of every symbol.
    let mut changed = vec![0u64; target + 1];
    for len in 1..=target {
        changed[len] = (
            surjective[len - 1]
                + (q as u64 - 1) * changed[len - 1] % MOD
        ) % MOD;
    }

    let minima: Vec<usize> = factors
        .iter()
        .map(|&is_changed| q + usize::from(is_changed))
        .collect();

    let mut remaining_min: usize = minima.iter().sum();
    let mut dp = vec![0u64; target + 1];
    dp[0] = 1;
    let mut low = 0usize;
    let mut high = 0usize;

    for (idx, &is_changed) in factors.iter().enumerate() {
        let min_len = minima[idx];
        remaining_min -= min_len;
        let new_high = target - remaining_min;
        let coeff = if is_changed {
            &changed
        } else {
            &surjective
        };

        let mut next = vec![0u64; target + 1];

        for current_len in low..=high {
            let current = dp[current_len];
            if current == 0 {
                continue;
            }

            let max_block_len = new_high - current_len;
            for block_len in min_len..=max_block_len {
                let ways = coeff[block_len];
                if ways == 0 {
                    continue;
                }

                let pos = current_len + block_len;
                let add = current * ways % MOD;
                let sum = next[pos] + add;
                next[pos] = if sum >= MOD { sum - MOD } else { sum };
            }
        }

        dp = next;
        low += min_len;
        high = new_high;
    }

    let mut out = io::BufWriter::new(io::stdout().lock());
    writeln!(out, "{}", dp[target]).unwrap();
}
